steps.script:
var main = tree.root.get_node("Main")
TerrainManager.set_meta("alo_saved_terrain", TerrainManager.terrain_features.duplicate(true))
TerrainManager.terrain_features = []
TerrainManager.emit_signal("terrain_loaded", TerrainManager.terrain_features)
var units = GameState.state["units"]
var keep = ["U_CUSTODIAN_GUARD_A", "U_BOYZ_B", "U_WARBOSS_A"]
for uid in units:
	if not uid in keep:
		for m in units[uid].get("models", []):
			m["alive"] = false
		continue
	var f = units[uid].get("flags", {})
	f["in_engagement"] = false
	f.erase("has_shot")
	f.erase("last_shot_idx")
	units[uid]["flags"] = f
var px = 40.0
var i = 0
for m in units["U_CUSTODIAN_GUARD_A"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (20.0 + i * 1.8) * px, "y": 10.0 * px}
		i += 1
var cg0 = units["U_CUSTODIAN_GUARD_A"]["models"][0]
var wb = units["U_WARBOSS_A"]["models"][0]
wb["position"] = {"x": 20.0 * px, "y": 34.6 * px}
var d = Measurement.model_to_model_distance_inches(cg0, wb)
wb["position"] = {"x": 20.0 * px, "y": (34.6 - (d - 23.0)) * px}
var wb_y = float(wb["position"]["y"]) / px
var j = 0
for m in units["U_BOYZ_B"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (16.0 + j * 1.4) * px, "y": (wb_y + 2.4) * px}
		j += 1
SettingsService.set_auto_allocate_wounds(true)
PhaseManager.get_current_phase_instance().update_local_state(GameState.create_snapshot())
main._recreate_unit_visuals()
main.get_node("ShootingController")._refresh_unit_list(false)
return "ok"

var b = GameState.create_snapshot(false)
var wid = ""
var uw = RulesEngine.get_unit_weapons("U_CUSTODIAN_GUARD_A", b)
for mid in uw:
	for w in uw[mid]:
		if str(RulesEngine.get_weapon_profile(w, b).get("type", "")).to_lower() != "melee":
			wid = str(w)
var near_boy = INF
for cm in b.units["U_CUSTODIAN_GUARD_A"].models:
	if not cm.get("alive", true):
		continue
	for bm in b.units["U_BOYZ_B"].models:
		if bm.get("alive", true):
			near_boy = minf(near_boy, Measurement.model_to_model_distance_inches(cm, bm))
var wb_d = Measurement.model_to_model_distance_inches(b.units["U_CUSTODIAN_GUARD_A"].models[0], b.units["U_WARBOSS_A"].models[0])
var esm = RulesEngine.get_eligible_shooter_models("U_CUSTODIAN_GUARD_A", wid, "U_BOYZ_B", b)
print("[attached_leader_only_in_range_shoot_11e] spear=%s Warboss %.2fin, nearest Boy %.2fin, per-model eligible=%s reasons=%s" % [wid, wb_d, near_boy, str(esm.eligible), str(esm.reasons)])
var ok = wb_d <= 24.0 and near_boy > 24.0 and RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_A", b).has("U_BOYZ_B") and esm.eligible.size() > 0
return "ok" if ok else "warboss=%.2f boy=%.2f eligible=%s" % [wb_d, near_boy, str(esm.eligible)]

var list = tree.root.get_node("Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/ShooterUnitList")
for i in list.item_count:
	if str(list.get_item_metadata(i)) == "U_CUSTODIAN_GUARD_A":
		return i
return -1

var p = PhaseManager.get_current_phase_instance()
var n = 0
for a in p.pending_assignments:
	if str(a.get("target_unit_id", "")) == "U_BOYZ_B":
		n += a.get("model_ids", []).size()
print("[attached_leader_only_in_range_shoot_11e] pending assignments: %s" % str(p.pending_assignments))
return n

var p = PhaseManager.get_current_phase_instance()
var rolls = 0
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY and str(d.get("context", "")) == "to_hit" and str(d.get("target_unit_id", "U_BOYZ_B")) == "U_BOYZ_B":
		rolls += d.get("rolls_raw", d.get("rolls", [])).size()
print("[attached_leader_only_in_range_shoot_11e] hit dice rolled at the Boyz: %d" % rolls)
return rolls

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[attached_leader_only_in_range_shoot_11e log] ERROR lines = ", n, " ", bad.slice(0, 3))
return n
